  },
  forest: {
    label: "Forest",
    a: "#84cc16",
    b: "#059669",
    c: "#0284c7",
    ink: "#052e16",
    actionInk: "#ffffff",
  },
  orchid: {
    label: "Orchid",
    a: "#d946ef",
    b: "#9333ea",
