export type VideoUrlResult =
  | { status: "supported"; provider: VideoProvider; src: string }
  | { status: "unsupported-provider"; provider: "loom" }
  | { status: "invalid" }

const VIDEO_FILE_EXTENSION = /\.(?:m4v|mov|mp4|ogv|webm)$/i
const YOUTUBE_VIDEO_ID = /^[A-Za-z0-9_-]{11}$/
const VIMEO_VIDEO_ID = /^\d+$/

function normalizedHost(url: URL): string {
  return url.hostname.toLowerCase().replace(/^www\./, "")
}

function isHost(host: string, domain: string): boolean {
  return host === domain || host.endsWith(`.${domain}`)
}

function youtubeVideoId(url: URL): string | null {
  const host = normalizedHost(url)
  if (host === "youtu.be") {
    const id = url.pathname.split("/").filter(Boolean)[0]
    return id && YOUTUBE_VIDEO_ID.test(id) ? id : null
  }
  if (!isHost(host, "youtube.com") && !isHost(host, "youtube-nocookie.com")) return null
  const segments = url.pathname.split("/").filter(Boolean)
  const candidate =
    url.pathname === "/watch"
      ? url.searchParams.get("v")
      : ["embed", "live", "shorts", "v"].includes(segments[0] ?? "")
        ? segments[1]
        : null
  return candidate && YOUTUBE_VIDEO_ID.test(candidate) ? candidate : null
}

function vimeoVideo(url: URL): { id: string; hash: string | null } | null {
  const host = normalizedHost(url)
  if (!isHost(host, "vimeo.com")) return null
  const segments = url.pathname.split("/").filter(Boolean)
  const idIndex =
    segments[0] === "video" ? 1 : segments.findIndex((part) => VIMEO_VIDEO_ID.test(part))
  const id = segments[idIndex]
  if (!id || !VIMEO_VIDEO_ID.test(id)) return null
  const candidateHash =
    url.searchParams.get("h") ?? url.searchParams.get("hash") ?? segments[idIndex + 1]
  const hash = candidateHash && /^[A-Za-z0-9]+$/.test(candidateHash) ? candidateHash : null
  return { id, hash }
}

function parsedUrl(value: string): { persisted: string; url: URL } | null {
  if (value.startsWith("/") && !value.startsWith("//")) {
    return { persisted: value, url: new URL(value, "https://cursare.invalid") }
  }
  try {
    const url = new URL(value)
    return url.protocol === "https:" ? { persisted: url.href, url } : null
  } catch {
    return null
  }
}

export function resolveVideoUrl(raw: string): VideoUrlResult {
  const value = raw.trim()
  if (!value || value.length > 2_048) return { status: "invalid" }
  const parsed = parsedUrl(value)
  if (!parsed) return { status: "invalid" }

  const youtubeId = youtubeVideoId(parsed.url)
  if (youtubeId) {
    return {
      status: "supported",
      provider: "youtube",
      src: `https://www.youtube.com/watch?v=${youtubeId}`,
    }
  }
  const vimeo = vimeoVideo(parsed.url)
  if (vimeo) {
    return {
      status: "supported",
      provider: "vimeo",
      src: `https://vimeo.com/${vimeo.id}${vimeo.hash ? `?h=${vimeo.hash}` : ""}`,
    }
  }
  if (isHost(normalizedHost(parsed.url), "loom.com")) {
    return { status: "unsupported-provider", provider: "loom" }
  }

  const path = parsed.url.pathname.toLowerCase()
  if (path.endsWith(".m3u8")) {
    return { status: "supported", provider: "hls", src: parsed.persisted }
  }
  if (VIDEO_FILE_EXTENSION.test(path)) {
    return { status: "supported", provider: "file", src: parsed.persisted }
  }
  return { status: "invalid" }
}

export function isVideoProvider(value: unknown): value is VideoProvider {
  return value === "file" || value === "hls" || value === "youtube" || value === "vimeo"
}

export function isSafeVideoSource(src: unknown, provider: unknown): boolean {
  if (src === null || src === "") return isVideoProvider(provider)
  if (typeof src !== "string" || !isVideoProvider(provider)) return false
  const resolved = resolveVideoUrl(src)
  return resolved.status === "supported" && resolved.provider === provider
}

"use client"

import { type ImgHTMLAttributes, useState } from "react"

export interface ContentCoverMediaProps
  extends Omit<ImgHTMLAttributes<HTMLImageElement>, "alt" | "className" | "src" | "style"> {
  src?: string | null
  alt?: string
  className?: string
  contentSlot?: string
  imageClassName?: string
}

export interface ContentCoverAttributionProps {
  creatorName?: string | null
  creatorUrl?: string | null
  sourceUrl?: string | null
  photoByLabel?: string
  onLabel?: string
}

function safeUnsplashUrl(value?: string | null): string | null {
  if (!value) return null
  try {
    const url = new URL(value)
    return url.protocol === "https:" && url.hostname === "unsplash.com" ? url.toString() : null
  } catch {
    return null
  }
}

export function ContentCoverAttribution({
  creatorName,
  creatorUrl,
  sourceUrl,
  photoByLabel = "Photo by",
  onLabel = "on",
}: ContentCoverAttributionProps) {
  const creatorHref = safeUnsplashUrl(creatorUrl)
  const sourceHref = safeUnsplashUrl(sourceUrl)
  if (!creatorName || !creatorHref || !sourceHref) return null

  return (
    <span className="content-cover-attribution">
      {photoByLabel}{" "}
      <a href={creatorHref} target="_blank" rel="noreferrer">
        {creatorName}
      </a>{" "}
      {onLabel}{" "}
      <a href={sourceHref} target="_blank" rel="noreferrer">
        Unsplash
      </a>
    </span>
  )
}

export function ContentCoverMedia({
  src,
  alt = "",
  className,
  contentSlot = "content-cover-media",
  imageClassName,
  onError,
  ...imageProps
}: ContentCoverMediaProps) {
  const [failedSrc, setFailedSrc] = useState<string | null>(null)
  const showsImage = Boolean(src && failedSrc !== src)

  return (
    <span
      data-slot={contentSlot}
      data-content-cover-kind={showsImage ? "image" : "fallback"}
      className={`content-cover-media ${className ?? ""}`}
    >
      <span className="content-cover-fallback" aria-hidden />
      {showsImage ? (
        <img
          {...imageProps}
          src={src ?? undefined}
          alt={alt}
          className={imageClassName}
          onError={(event) => {
            setFailedSrc(src ?? null)
            onError?.(event)
          }}
        />
      ) : null}
    </span>
  )
}

import { cn } from "@/lib/utils"
import {
  type ComponentPropsWithoutRef,
  type CSSProperties,
  cloneElement,
  type HTMLAttributes,
  type ReactElement,
  type ReactNode,
} from "react"
import {
  type LearnerComponentKey,
  type LearnerEffect,
  type LearnerMeasure as LearnerMeasureRole,
  type LearnerSurface as LearnerSurfaceRole,
  learnerComponentAttributes,
} from "./learner-component-registry"

export type LearnerRootElement =
  | "a"
  | "article"
  | "aside"
  | "blockquote"
  | "div"
  | "figure"
  | "footer"
  | "h1"
  | "h2"
  | "h3"
  | "h4"
  | "h5"
  | "h6"
  | "header"
  | "hr"
  | "li"
  | "main"
  | "nav"
  | "ol"
  | "p"
  | "section"
  | "span"
  | "table"
  | "ul"

export interface LearnerRootProps extends HTMLAttributes<HTMLElement> {
  as?: LearnerRootElement
  contractKey: LearnerComponentKey
  download?: boolean | string
  href?: string
  rel?: string
  render?: ReactElement
  start?: number
  target?: string
}

export function LearnerRoot({ as, contractKey, className, render, ...props }: LearnerRootProps) {
  const contractProps = learnerComponentAttributes(contractKey)
  if (render) {
    const renderedRoot = render as ReactElement<{
      className?: string
      "data-learner-visual-owner"?: "host"
    }>
    return cloneElement(renderedRoot, {
      ...props,
      ...contractProps,
      "data-learner-visual-owner": "host",
      className: cn("learner-component", renderedRoot.props.className, className),
    })
  }

  const Component = as ?? "div"
  return <Component {...props} {...contractProps} className={cn("learner-component", className)} />
}

interface LearnerSurfaceProps extends ComponentPropsWithoutRef<"div"> {
  surface: LearnerSurfaceRole
}

export function LearnerSurfaceRegion({ surface, className, ...props }: LearnerSurfaceProps) {
  return (
    <div data-learner-surface={surface} className={cn("learner-surface", className)} {...props} />
  )
}

interface LearnerMeasureProps extends ComponentPropsWithoutRef<"div"> {
  measure: LearnerMeasureRole
}

export function LearnerMeasureRegion({ measure, className, ...props }: LearnerMeasureProps) {
  return (
